    for char in text:
        if 'A' <= char <= 'Z':
            shifted_char_code = (ord(char) - ORD_A_UPPER + shift) % ALPHABET_SIZE + ORD_A_UPPER
            result_chars.append(chr(shifted_char_code))
        elif 'a' <= char <= 'z':
            shifted_char_code = (ord(char) - ORD_A_LOWER + shift) % ALPHABET_SIZE + ORD_A_LOWER
